	"/Lotus/Language/Suits/CalibanDeluxeHelmetDesc": {
		"de": "Caliban Orfeos bevorzugter Helm.",
		"en": "Caliban Orfeo's signature helmet.",
		"es": "Casco distintivo de Caliban Orfeo.",
		"fr": "Le Casque emblématique de Caliban Orfeo.",
