	"/Lotus/Language/Suits/KoumeiAltHelmDesc": {
		"de": "Blicke auf den Stern des Webers.",
		"en": "Gaze upon the Weaver Star.",
		"es": "Contempla a la estrella tejedora",
		"fr": "Contemplez la tisserande du destin.",
		"it": "Contempla la Stella Tessitrice del Destino.",
		"ja": "結ばれた星々を眺めよう。",
		"ko": "직녀성을 올려다보세요.",
		"pl": "Kontempluj gwiazdę tkaczki.",
		"pt": "Contemple a Estrela Tecelã.",
		"ru": "Созерцайте звезду ткачихи.",
		"tc": "凝望織女星。",
		"th": "จ้องมองดูดวงดาวเจ้าหญิงทอผ้า",
		"tr": "İşte karşınızda Kaderin Ağlarını Ören Yıldız.",
		"uk": "Помилуйтеся на зорю Ткаля.",
		"zh": "凝视织女星。"
	},
